spec.setup_code:
var XH = 'x̂';
var INK = '#04204B', SEC = '#3D5F91', GUIDE = '#8098BC', BLUE = '#0B4FC0', WARM = '#B4552F', TEAL = '#138374';
var N = 50, G = 12, NB = 30, PERIOD = 14;
function rng(seed) { var a = seed; return function () { a = (a + 0x6D2B79F5) | 0; var t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
var rand = rng(12345);

// ---------- image model: target smiley and blurred predictions ----------
var T0 = [];
for (var r = 0; r < G; r++) for (var c = 0; c < G; c++) {
  var x = c + 0.5, y = r + 0.5, v = 0;
  var dc = Math.sqrt((x - 6) * (x - 6) + (y - 6) * (y - 6));
  if (dc > 3.9 && dc < 5.4) v = 1;
  if ((x - 4.4) * (x - 4.4) + (y - 4.6) * (y - 4.6) < 0.9) v = 1;
  if ((x - 7.6) * (x - 7.6) + (y - 4.6) * (y - 4.6) < 0.9) v = 1;
  if (y > 7.2 && y < 8.6 && Math.abs(x - 6) < 2.2 + (y - 7.2) * 0.5) v = 1;
  if (y > 8.6 && y < 9.2 && Math.abs(x - 6) > 1.6 && Math.abs(x - 6) < 2.8) v = 1;
  T0.push(v);
}
var mean0 = 0; for (var i = 0; i < T0.length; i++) mean0 += T0[i]; mean0 /= T0.length;
function imgAt(p) {
  var sg = 0.06 + 3.0 * Math.pow(Math.max(0, 1 - p), 1.8);
  var cc = 0.4 + 0.6 * p;
  var out = [], k2 = 1 / (2 * sg * sg);
  for (var r = 0; r < G; r++) for (var c = 0; c < G; c++) {
    var sw = 0, sv = 0;
    for (var r2 = 0; r2 < G; r2++) for (var c2 = 0; c2 < G; c2++) {
      var w = Math.exp(-((r - r2) * (r - r2) + (c - c2) * (c - c2)) * k2);
      sw += w; sv += w * T0[r2 * G + c2];
    }
    out.push(mean0 + cc * (sv / sw - mean0));
  }
  return out;
}
var imgs = [], dImg = [];
var prevI = imgAt(-1 / 49);
var maxI = 0;
for (var k = 1; k <= N; k++) {
  var cur = imgAt((k - 1) / 49);
  var s2 = 0; for (var i = 0; i < cur.length; i++) s2 += (cur[i] - prevI[i]) * (cur[i] - prevI[i]);
  dImg[k] = Math.sqrt(s2 / cur.length); maxI = Math.max(maxI, dImg[k]);
  imgs[k] = cur; prevI = cur;
}
for (var k = 1; k <= N; k++) dImg[k] /= maxI;

// ---------- co-folding model: chain beads ----------
var TG = [], NZ = [];
for (var i = 0; i < NB; i++) {
  var t = i / (NB - 1);
  var a = t * 2.6 * Math.PI + 0.3;
  var rr = 1 - 0.55 * t + 0.07 * Math.sin(i * 1.9);
  TG.push([rr * Math.cos(a), rr * Math.sin(a)]);
  NZ.push([(rand() + rand() + rand() - 1.5) * 0.9, (rand() + rand() + rand() - 1.5) * 0.9]);
}
var cx0 = 0, cy0 = 0;
for (var i = 0; i < NB; i++) { cx0 += TG[i][0] / NB; cy0 += TG[i][1] / NB; }
var xh = [], dCh = [], prevC = [], maxC = 0;
for (var i = 0; i < NB; i++) prevC.push([cx0 + 0.15 * (TG[i][0] - cx0), cy0 + 0.15 * (TG[i][1] - cy0)]);
for (var k = 1; k <= N; k++) {
  var A = 0.05 * Math.exp(-(k - 1) / 5) + 0.004;
  var cur = [], s2 = 0;
  for (var i = 0; i < NB; i++) {
    var p2 = [TG[i][0] + (rand() - 0.5) * 2 * A, TG[i][1] + (rand() - 0.5) * 2 * A];
    cur.push(p2);
    s2 += (p2[0] - prevC[i][0]) * (p2[0] - prevC[i][0]) + (p2[1] - prevC[i][1]) * (p2[1] - prevC[i][1]);
  }
  dCh[k] = Math.sqrt(s2 / NB); maxC = Math.max(maxC, dCh[k]);
  xh[k] = cur; prevC = cur;
}
for (var k = 1; k <= N; k++) dCh[k] /= maxC;

// ---------- helpers ----------
function txt(ctx, s, x, y, align, color, size, bold) {
  ctx.font = (bold ? 'bold ' : '') + size + 'px sans-serif';
  ctx.fillStyle = color; ctx.textAlign = align; ctx.textBaseline = 'alphabetic';
  ctx.fillText(s, x, y);
}
function mk(px, py, pw, ph, stacked) {
  var o = { px: px, py: py, pw: pw, ph: ph, stacked: stacked };
  if (!stacked) {
    var s = Math.max(60, Math.min(pw - 24, 190, ph - 170));
    o.s = s; o.ax = px + (pw - s) / 2; o.ay = py + 30;
    o.cx = px + 34; o.cw = pw - 46; o.cy = o.ay + s + 36; o.ch = py + ph - 24 - o.cy;
    o.stepX = o.ax + s / 2; o.stepY = o.ay + s + 13; o.ctY = o.ay + s + 30;
  } else {
    var s = Math.max(60, Math.min(ph - 50, pw * 0.42));
    o.s = s; o.ax = px + 8; o.ay = py + 26;
    o.cx = px + s + 8 + 34; o.cw = pw - (s + 8 + 34) - 12; o.cy = py + 46; o.ch = ph - 46 - 26;
    o.stepX = o.ax + s / 2; o.stepY = o.ay + s + 13; o.ctY = o.cy - 6;
  }
  return o;
}
function curve(ctx, L, d, k, col, fs) {
  var x0 = L.cx, y0 = L.cy + L.ch, w = L.cw, h = L.ch;
  ctx.strokeStyle = GUIDE; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(x0, L.cy); ctx.lineTo(x0, y0); ctx.lineTo(x0 + w, y0); ctx.stroke();
  txt(ctx, 'change in ' + XH + ' per step', x0, L.ctY, 'left', SEC, fs);
  txt(ctx, '1', x0, y0 + 12, 'center', SEC, fs);
  txt(ctx, '50', x0 + w, y0 + 12, 'center', SEC, fs);
  txt(ctx, 'step', x0 + w / 2, y0 + 12, 'center', SEC, fs);
  txt(ctx, '0', x0 - 5, y0, 'right', SEC, fs);
  ctx.globalAlpha *= 0.35; ctx.strokeStyle = col; ctx.lineWidth = 1.2; ctx.beginPath();
  for (var j = 1; j <= N; j++) { var X = x0 + (j - 1) / 49 * w, Y = y0 - d[j] * h * 0.92; if (j === 1) ctx.moveTo(X, Y); else ctx.lineTo(X, Y); }
  ctx.stroke(); ctx.globalAlpha /= 0.35;
  ctx.lineWidth = 2.2; ctx.beginPath();
  for (var j = 1; j <= k; j++) { var X = x0 + (j - 1) / 49 * w, Y = y0 - d[j] * h * 0.92; if (j === 1) ctx.moveTo(X, Y); else ctx.lineTo(X, Y); }
  ctx.stroke();
  ctx.fillStyle = col; ctx.beginPath();
  ctx.arc(x0 + (k - 1) / 49 * w, y0 - d[k] * h * 0.92, 3.5, 0, 6.2832); ctx.fill();
}
function chainPath(ctx, pts, sc, ox, oy) {
  ctx.beginPath();
  for (var i = 0; i < pts.length; i++) { var X = ox + pts[i][0] * sc, Y = oy + pts[i][1] * sc; if (i === 0) ctx.moveTo(X, Y); else ctx.lineTo(X, Y); }
  ctx.stroke();
}
function beads(ctx, pts, sc, ox, oy, rad) {
  for (var i = 0; i < pts.length; i++) { ctx.beginPath(); ctx.arc(ox + pts[i][0] * sc, oy + pts[i][1] * sc, rad, 0, 6.2832); ctx.fill(); }
}
var CAPS = ['Step 1: both models already output a first guess ' + XH, 'Sampling: image ' + XH + ' sharpens, fold ' + XH + ' stays put', 'Step 50: image ' + XH + ' is sharp only at the end', XH + ' nearly final at step 1: the open question'];
var STARTS = [0, 2.5, 10.5, 12.2];

return {
  draw: function (ctx, width, height, time, dt) {
    ctx.globalAlpha = 1; ctx.fillStyle = '#ffffff'; ctx.fillRect(0, 0, width, height);
    var t = time % PERIOD;
    var sf = 1, ph = 0;
    if (t < 2.5) { sf = 1; ph = 0; }
    else if (t < 10.5) { var u = (t - 2.5) / 8; sf = 1 + 49 * u * u * (2.2 - 1.2 * u); ph = 1; }
    else { sf = 50; ph = t < 12.2 ? 2 : 3; }
    var k = Math.max(1, Math.min(N, Math.floor(sf + 0.0001)));
    var p = (sf - 1) / 49;
    var fs = width < 500 ? 11 : 12;

    // layout
    var stacked = width < 620, m = 12, top = 34, P = [];
    if (!stacked) {
      var pw = (width - 3 * m) / 2, phh = height - top - 10;
      P.push(mk(m, top, pw, phh, false)); P.push(mk(2 * m + pw, top, pw, phh, false));
    } else {
      var phs = (height - top - 16) / 2, pws = width - 2 * m;
      P.push(mk(m, top, pws, phs, true)); P.push(mk(m, top + phs + 8, pws, phs, true));
    }

    // phase caption
    var ca = Math.min(1, (t - STARTS[ph]) / 0.35);
    var cs = width < 500 ? 11 : 13;
    ctx.font = 'bold ' + cs + 'px sans-serif';
    while (cs > 11 && ctx.measureText(CAPS[ph]).width > width - 16) { cs -= 1; ctx.font = 'bold ' + cs + 'px sans-serif'; }
    ctx.globalAlpha = ca; txt(ctx, CAPS[ph], width / 2, 20, 'center', ph === 3 ? WARM : INK, cs, true); ctx.globalAlpha = 1;

    // ---------- left: image model ----------
    var L = P[0];
    ctx.strokeStyle = GUIDE; ctx.lineWidth = 1; ctx.strokeRect(L.px + 0.5, L.py + 0.5, L.pw - 1, L.ph - 1);
    txt(ctx, 'Image model', L.px + 8, L.py + 16, 'left', INK, 13, true);
    txt(ctx, 'predicted ' + XH + ' (12×12)', L.px + L.pw - 8, L.py + 16, 'right', SEC, fs);
    var im = imgs[k], cell = L.s / G;
    for (var r = 0; r < G; r++) for (var c = 0; c < G; c++) {
      var v = Math.max(0, Math.min(1, im[r * G + c]));
      ctx.fillStyle = 'rgb(' + Math.round(240 + (4 - 240) * v) + ',' + Math.round(244 + (32 - 244) * v) + ',' + Math.round(251 + (75 - 251) * v) + ')';
      ctx.fillRect(L.ax + c * cell, L.ay + r * cell, cell + 0.6, cell + 0.6);
    }
    ctx.strokeStyle = GUIDE; ctx.strokeRect(L.ax, L.ay, L.s, L.s);
    txt(ctx, 'step ' + k + ' / 50', L.stepX, L.stepY, 'center', INK, fs);
    curve(ctx, L, dImg, k, BLUE, fs);

    // ---------- right: co-folding model ----------
    var R = P[1];
    ctx.strokeStyle = GUIDE; ctx.lineWidth = 1; ctx.strokeRect(R.px + 0.5, R.py + 0.5, R.pw - 1, R.ph - 1);
    txt(ctx, 'Co-folding model', R.px + 8, R.py + 16, 'left', INK, 13, true);
    var lx = R.px + R.pw - 8;
    txt(ctx, 'x (noisy)', lx, R.py + 16, 'right', SEC, fs);
    ctx.font = fs + 'px sans-serif';
    var wN = ctx.measureText('x (noisy)').width;
    ctx.globalAlpha = 0.4; ctx.fillStyle = SEC; ctx.beginPath(); ctx.arc(lx - wN - 8, R.py + 12, 3.5, 0, 6.2832); ctx.fill(); ctx.globalAlpha = 1;
    var xl = lx - wN - 20;
    txt(ctx, XH, xl, R.py + 16, 'right', SEC, fs);
    ctx.fillStyle = WARM; ctx.beginPath(); ctx.arc(xl - 12, R.py + 12, 3.5, 0, 6.2832); ctx.fill();
    ctx.strokeStyle = GUIDE; ctx.strokeRect(R.ax, R.ay, R.s, R.s);
    var sc = R.s / 2 / 1.5, ox = R.ax + R.s / 2, oy = R.ay + R.s / 2;
    var nz = Math.pow(Math.max(0, 1 - p), 1.3);
    var xs = [];
    for (var i = 0; i < NB; i++) xs.push([TG[i][0] + (NZ[i][0] - TG[i][0]) * nz, TG[i][1] + (NZ[i][1] - TG[i][1]) * nz]);
    var rad = Math.max(2.5, R.s * 0.02);
    ctx.globalAlpha = 0.3; ctx.strokeStyle = SEC; ctx.fillStyle = SEC; ctx.lineWidth = 1;
    chainPath(ctx, xs, sc, ox, oy); beads(ctx, xs, sc, ox, oy, rad * 0.9);
    ctx.globalAlpha = 1; ctx.strokeStyle = WARM; ctx.fillStyle = WARM; ctx.lineWidth = 1.6;
    chainPath(ctx, xh[k], sc, ox, oy); beads(ctx, xh[k], sc, ox, oy, rad);
    txt(ctx, 'step ' + k + ' / 50', R.stepX, R.stepY, 'center', INK, fs);
    curve(ctx, R, dCh, k, WARM, fs);
    if (k === 1 || ph === 3) {
      var hl = ph === 3 ? 'first step: big jump, then ~0' : 'x̂ ≈ final shape';
      var hx = R.cx + R.cw * 0.28, hy = R.cy + R.ch * 0.45;
      txt(ctx, hl, Math.min(hx + 40, R.cx + R.cw - 2), hy, 'center', WARM, fs);
    }

    // fade at loop boundaries
    var f = 1;
    if (t < 0.5) f = t / 0.5; else if (t > 13.4) f = (PERIOD - t) / 0.6;
    if (f < 1) { ctx.globalAlpha = 1 - f; ctx.fillStyle = '#ffffff'; ctx.fillRect(0, 0, width, height); ctx.globalAlpha = 1; }
  }
};
